class ClinicalCaseLearningScreen extends StatelessWidget {
  const ClinicalCaseLearningScreen({super.key});
  @override
  Widget build(BuildContext context) => Scaffold(
    backgroundColor: AtlasColors.ivory,
    appBar: AppBar(title: const Text('Clinical Case-Based Learning')),
    body: StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(
      stream: FirebaseFirestore.instance.collection('clinical_cases').where('isPublished',isEqualTo:true).snapshots(),
      builder: (context,s) {
        if(s.hasError) return Center(child: Text('Unable to load cases: ${s.error}'));
        if(!s.hasData) return const Center(child:CircularProgressIndicator());
        final docs=[...s.data!.docs]..sort((a,b)=>(b.data()['updatedAt'] as Timestamp? ?? Timestamp(0,0)).compareTo(a.data()['updatedAt'] as Timestamp? ?? Timestamp(0,0)));
        if(docs.isEmpty) return const _EmptyState('No clinical cases are available yet. Check again soon.',Icons.medical_information_rounded);
        return ListView.builder(padding:const EdgeInsets.all(16),itemCount:docs.length,itemBuilder:(c,i){
          final d=docs[i].data();
          return Card(margin:const EdgeInsets.only(bottom:13),child:ListTile(
            contentPadding:const EdgeInsets.all(16),leading:const CircleAvatar(backgroundColor:AtlasColors.paleBlue,child:Icon(Icons.medical_services_rounded,color:AtlasColors.royalBlue)),
            title:Text((d['title']??'Clinical case').toString(),style:const TextStyle(color:AtlasColors.navy,fontWeight:FontWeight.w900)),
            subtitle:Padding(padding:const EdgeInsets.only(top:7),child:Text('${d['specialty']??'General medicine'} • ${d['difficulty']??'Standard'}\n${d['summary']??''}',style:const TextStyle(color:AtlasColors.secondaryText,height:1.45))),
            trailing:const Icon(Icons.chevron_right,color:AtlasColors.royalBlue),
            onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ClinicalCaseDetailScreen(caseId:docs[i].id,data:d))),
          ));
        });
      },
    ),
  );
}

class ClinicalCaseDetailScreen extends StatefulWidget {
  final String caseId; final Map<String,dynamic> data;
  const ClinicalCaseDetailScreen({super.key,required this.caseId,required this.data});
  @override State<ClinicalCaseDetailScreen> createState()=>_ClinicalCaseDetailScreenState();
}
class _ClinicalCaseDetailScreenState extends State<ClinicalCaseDetailScreen>{
  final Map<int,String> selected={}; bool submitted=false;
  @override Widget build(BuildContext context){
    final d=widget.data; final questions=d['questions'] is List?List<Map<String,dynamic>>.from((d['questions'] as List).whereType<Map>().map((e)=>Map<String,dynamic>.from(e))):<Map<String,dynamic>>[];
    return Scaffold(backgroundColor:AtlasColors.ivory,appBar:AppBar(title:const Text('Case Investigation')),body:ListView(padding:const EdgeInsets.all(17),children:[
      _CasePanel(title:'Patient presentation',icon:Icons.person_search_rounded,body:(d['scenario']??d['summary']??'').toString()),
      _CasePanel(title:'History & examination',icon:Icons.assignment_ind_rounded,body:(d['history']??'Not provided').toString()),
      _CasePanel(title:'Vitals and investigations',icon:Icons.monitor_heart_rounded,body:(d['vitals']??'Not provided').toString()+'\n\n'+(d['investigations']??'Not provided').toString()),
      _CasePanel(title:'Clinical findings',icon:Icons.biotech_rounded,body:(d['findings']??'Not provided').toString()),
      const SizedBox(height:18),const Text('Clinical decision points',style:TextStyle(color:AtlasColors.navy,fontSize:19,fontWeight:FontWeight.w900)),
      if(questions.isEmpty)const Text('The instructor has not added decision questions for this case yet.',style:TextStyle(color:AtlasColors.secondaryText)),
      ...List.generate(questions.length,(i){final q=questions[i];final opts=List<String>.from(q['options']??const []);return Card(margin:const EdgeInsets.only(top:12),child:Padding(padding:const EdgeInsets.all(15),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
        Text('STEP ${i+1}',style:const TextStyle(color:AtlasColors.royalBlue,fontSize:10,fontWeight:FontWeight.w900)),const SizedBox(height:8),Text((q['question']??'').toString(),style:const TextStyle(color:AtlasColors.charcoal,fontWeight:FontWeight.w800)),
        ...List.generate(opts.length,(j)=>RadioListTile<String>(dense:true,contentPadding:EdgeInsets.zero,title:Text(opts[j],style:const TextStyle(color:AtlasColors.charcoal,fontSize:13)),value:String.fromCharCode(65+j),groupValue:selected[i],onChanged:submitted?null:(v)=>setState(()=>selected[i]=v!))),
        if(submitted)Container(width:double.infinity,padding:const EdgeInsets.all(11),decoration:BoxDecoration(color:selected[i]==q['correctAnswer']?const Color(0xFFE8F5EC):const Color(0xFFFFEEEE),borderRadius:BorderRadius.circular(12)),child:Text('Correct answer: ${q['correctAnswer']??'Not supplied'}\n${q['explanation']??''}',style:const TextStyle(color:AtlasColors.charcoal,height:1.5)))
      ])));}),
      if(questions.isNotEmpty)Padding(padding:const EdgeInsets.only(top:16),child:FilledButton.icon(onPressed:()=>setState(()=>submitted=true),icon:const Icon(Icons.fact_check_rounded),label:Text(submitted?'Review completed':'Submit clinical decisions'))),
      if((d['management']??'').toString().isNotEmpty)_CasePanel(title:'Management and debrief',icon:Icons.health_and_safety_rounded,body:d['management'].toString()),
      const SizedBox(height:24),
    ]));
  }
}
class _CasePanel extends StatelessWidget{final String title,body;final IconData icon;const _CasePanel({required this.title,required this.body,required this.icon});@override Widget build(BuildContext context)=>Card(margin:const EdgeInsets.only(bottom:10),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Icon(icon,color:AtlasColors.royalBlue),const SizedBox(width:9),Text(title,style:const TextStyle(color:AtlasColors.navy,fontWeight:FontWeight.w900))]),const SizedBox(height:10),Text(body,style:const TextStyle(color:AtlasColors.charcoal,height:1.6))])));}

class MistakesNotebookScreen extends StatefulWidget{const MistakesNotebookScreen({super.key});@override State<MistakesNotebookScreen> createState()=>_MistakesNotebookScreenState();}
class _MistakesNotebookScreenState extends State<MistakesNotebookScreen>{
 final uid=FirebaseAuth.instance.currentUser?.uid;
 Future<void> importMistakes()async{
  if(uid==null)return;final db=FirebaseFirestore.instance;
  final attempts=await db.collection('mcq_attempts').where('userId',isEqualTo:uid).get();int added=0;
  final batch=db.batch();
  for(final doc in attempts.docs){final answers=doc.data()['answers'];if(answers is! List)continue;for(var i=0;i<answers.length;i++){final raw=answers[i];if(raw is! Map)continue;final a=Map<String,dynamic>.from(raw);if(a['isCorrect']==true||a['question']==null)continue;final id='${doc.id}_$i';final ref=db.collection('mistake_notebook').doc('${uid}_$id');batch.set(ref,{'userId':uid,'attemptId':doc.id,'questionIndex':i,'question':a['question'],'options':a['options']??[],'selectedAnswer':a['selectedAnswer'],'correctAnswer':a['correctAnswer'],'explanation':a['explanation']??'','subject':a['subject']??'','topic':a['topic']??'','isReviewed':false,'createdAt':FieldValue.serverTimestamp()},SetOptions(merge:true));added++;}
  }
  await batch.commit();if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$added incorrect or unanswered questions synced to your notebook.')));
 }
 Future<void> updateNote(String id,Map<String,dynamic> data)async{final c=TextEditingController(text:(data['personalNote']??'').toString());final v=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Your revision note'),content:TextField(controller:c,minLines:3,maxLines:6,decoration:const InputDecoration(hintText:'Why was this difficult? What will you remember?')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,c.text),child:const Text('Save'))]));if(v!=null){await FirebaseFirestore.instance.collection('mistake_notebook').doc(id).update({'personalNote':v,'isReviewed':true,'reviewedAt':FieldValue.serverTimestamp()});}}
 @override Widget build(BuildContext context)=>Scaffold(backgroundColor:AtlasColors.ivory,appBar:AppBar(title:const Text('Mistakes Notebook'),actions:[IconButton(tooltip:'Sync incorrect answers from attempts',onPressed:importMistakes,icon:const Icon(Icons.sync_rounded))]),floatingActionButton:FloatingActionButton.extended(onPressed:importMistakes,icon:const Icon(Icons.download_rounded),label:const Text('Sync mistakes')),body:uid==null?const SizedBox():StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('mistake_notebook').where('userId',isEqualTo:uid).snapshots(),builder:(c,s){if(s.hasError)return Center(child:Text('Unable to load notebook: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=s.data!.docs;if(docs.isEmpty)return const _EmptyState('Your incorrect and unanswered questions will appear here. Tap Sync mistakes to import your exam history.',Icons.menu_book_rounded);return ListView(padding:const EdgeInsets.all(15),children:[Text('${docs.length} saved revision items',style:const TextStyle(color:AtlasColors.secondaryText,fontWeight:FontWeight.w700)),const SizedBox(height:12),...docs.map((doc){final d=doc.data();return Card(margin:const EdgeInsets.only(bottom:10),child:Padding(padding:const EdgeInsets.all(15),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text((d['subject']??'General').toString()+' • '+(d['topic']??'').toString(),style:const TextStyle(color:AtlasColors.royalBlue,fontSize:10,fontWeight:FontWeight.w900))),Chip(label:Text(d['isReviewed']==true?'Reviewed':'To review'),backgroundColor:d['isReviewed']==true?const Color(0xFFE8F5EC):const Color(0xFFFFF3D9))]),Text((d['question']??'').toString(),style:const TextStyle(color:AtlasColors.navy,fontWeight:FontWeight.w800,height:1.5)),const SizedBox(height:8),Text('Your answer: ${d['selectedAnswer']??'Skipped'}   •   Correct: ${d['correctAnswer']??'—'}',style:const TextStyle(color:AtlasColors.charcoal,fontSize:12)),if((d['explanation']??'').toString().isNotEmpty)Padding(padding:const EdgeInsets.only(top:8),child:Text(d['explanation'].toString(),style:const TextStyle(color:AtlasColors.secondaryText,height:1.5))),if((d['personalNote']??'').toString().isNotEmpty)Padding(padding:const EdgeInsets.only(top:8),child:Text('My note: ${d['personalNote']}',style:const TextStyle(color:AtlasColors.charcoal,fontStyle:FontStyle.italic))),Align(alignment:Alignment.centerRight,child:TextButton.icon(onPressed:()=>updateNote(doc.id,d),icon:const Icon(Icons.edit_note_rounded),label:const Text('Add revision note')))])));})]);}));
}

class MockExamPredictionScreen extends StatelessWidget{const MockExamPredictionScreen({super.key});@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser?.uid;return Scaffold(backgroundColor:AtlasColors.ivory,appBar:AppBar(title:const Text('Mock Exam Readiness')),body:uid==null?const SizedBox():StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('mcq_attempts').where('userId',isEqualTo:uid).snapshots(),builder:(c,s){if(s.hasError)return Center(child:Text('Unable to analyse results: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final docs=s.data!.docs;final scores=docs.map((d)=>(d.data()['percentage'] as num?)?.toDouble()).whereType<double>().toList();scores.sort();if(scores.isEmpty)return const _EmptyState('Complete a few practice examinations to unlock your readiness analysis.',Icons.insights_rounded);final recent=scores.reversed.take(10).toList();final avg=recent.reduce((a,b)=>a+b)/recent.length;final confidence=(avg*(0.75+0.25*(recent.length/10))).clamp(0,100).toDouble();final label=confidence>=85?'Strong readiness':confidence>=70?'Promising progress':confidence>=50?'Developing readiness':'More preparation recommended';final subjects=<String,List<double>>{};for(final doc in docs){final answers=doc.data()['answers'];if(answers is! List)continue;for(final raw in answers){if(raw is! Map)continue;final a=Map<String,dynamic>.from(raw);final sub=(a['subject']??'General').toString();subjects.putIfAbsent(sub,()=>[]).add(a['isCorrect']==true?100:0);}}final weak=subjects.entries.map((e)=>MapEntry(e.key,e.value.reduce((a,b)=>a+b)/e.value.length)).toList()..sort((a,b)=>a.value.compareTo(b.value));return ListView(padding:const EdgeInsets.all(18),children:[Container(padding:const EdgeInsets.all(23),decoration:BoxDecoration(gradient:const LinearGradient(colors:[AtlasColors.navy,AtlasColors.royalBlue]),borderRadius:BorderRadius.circular(22)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('ESTIMATED EXAM READINESS',style:TextStyle(color:AtlasColors.champagne,fontWeight:FontWeight.w900,letterSpacing:1)),const SizedBox(height:12),Text('${confidence.toStringAsFixed(1)}%',style:const TextStyle(color:Colors.white,fontSize:42,fontWeight:FontWeight.w900)),Text(label,style:const TextStyle(color:AtlasColors.champagne,fontWeight:FontWeight.w800)),const SizedBox(height:14),LinearProgressIndicator(value:confidence/100,minHeight:9,backgroundColor:Colors.white24,color:AtlasColors.champagne),const SizedBox(height:12),Text('Based on ${recent.length} recent scored attempts (average ${avg.toStringAsFixed(1)}%).',style:const TextStyle(color:Colors.white70))]),),const SizedBox(height:17),const Text('Priority revision areas',style:TextStyle(color:AtlasColors.navy,fontSize:18,fontWeight:FontWeight.w900)),const SizedBox(height:9),if(weak.isEmpty)const Text('Subject-level detail will appear as more reviewed questions are recorded.') else ...weak.take(8).map((e)=>Card(child:ListTile(title:Text(e.key,style:const TextStyle(color:AtlasColors.navy,fontWeight:FontWeight.w800)),subtitle:LinearProgressIndicator(value:e.value/100,color:e.value<50?AtlasColors.error:AtlasColors.royalBlue),trailing:Text('${e.value.toStringAsFixed(0)}%'))),const SizedBox(height:14),const Text('This is an educational estimate, not a validated prediction or guarantee of examination performance. More attempts and representative full-length mocks improve reliability.',style:TextStyle(color:AtlasColors.secondaryText,fontSize:11,height:1.5))]);}));}}

